#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long minInitialStrength(std::vector<int>& damage, int armor) {
        long long totalDmg = 0;
        int maxSingle = 0;
        for (int d : damage) {
            totalDmg += d;
            maxSingle = std::max(maxSingle, d);
        }
        int absorb = std::min(maxSingle, armor);
        return totalDmg - absorb + 1;
    }
};

